// Generated by asset-cache-plugin.mjs; served at the application base URL.
const cachePrefix = `dontstarve-assets:${self.registration.scope}:`;
const cacheName = `${cachePrefix}__ASSET_CACHE_VERSION__`;
const assetRoots = __ASSET_CACHE_DIRECTORIES__.map(
  directory => new URL(directory, self.registration.scope).href,
);

// Keep the default waiting lifecycle: an update must not replace assets in a running game.
self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names
      .filter(name => name.startsWith(cachePrefix) && name !== cacheName)
      .map(name => caches.delete(name)));
    await self.clients.claim();
  })());
});

async function loadAsset(request) {
  let cache;
  try {
    cache = await caches.open(cacheName);
    const cached = await cache.match(request);
    if (cached) return cached;
  } catch (error) {
    console.warn('Unable to read asset cache', error);
  }

  // Revalidate the HTTP cache when populating a new content version.
  const response = await fetch(request, { cache: 'no-cache' });
  if (cache && response.status === 200 && !response.redirected &&
      !response.headers.get('content-type')?.includes('text/html')) {
    try {
      await cache.put(request, response.clone());
    } catch (error) {
      // Quota/privacy restrictions must not prevent online resource loading.
      console.warn('Unable to write asset cache', error);
    }
  }
  return response;
}

async function loadRange(request, range) {
  // Media elements request byte ranges. Cache a complete file, then serve its slice.
  const headers = new Headers(request.headers);
  headers.delete('range');
  const response = await loadAsset(new Request(request, { headers }));
  if (response.status !== 200) return response;

  const data = await response.arrayBuffer();
  const length = data.byteLength;
  const start = range[1] ? Number(range[1]) : Math.max(0, length - Number(range[2]));
  const end = range[1] && range[2] ? Math.min(Number(range[2]), length - 1) : length - 1;
  const responseHeaders = new Headers(response.headers);
  // The cached response body is already decoded by fetch().
  responseHeaders.delete('content-encoding');
  responseHeaders.set('accept-ranges', 'bytes');

  if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end) || start > end || start >= length) {
    responseHeaders.set('content-range', `bytes */${length}`);
    responseHeaders.set('content-length', '0');
    return new Response(null, { status: 416, headers: responseHeaders });
  }

  responseHeaders.set('content-range', `bytes ${start}-${end}/${length}`);
  responseHeaders.set('content-length', String(end - start + 1));
  return new Response(data.slice(start, end + 1), { status: 206, headers: responseHeaders });
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET' || request.cache === 'no-store' ||
      !assetRoots.some(root => request.url.startsWith(root))) return;

  const rangeHeader = request.headers.get('range');
  if (rangeHeader !== null) {
    const range = /^bytes=(\d*)-(\d*)$/.exec(rangeHeader);
    // Leave multipart ranges and conditional ranges to the server.
    if (!range || (!range[1] && !range[2]) || request.headers.has('if-range')) return;
    event.respondWith(loadRange(request, range));
  } else {
    event.respondWith(loadAsset(request));
  }
});
